<?php
require __DIR__.'/config.php';require __DIR__.'/functions.php';requireLogin();
if(user()['role']!=='customer') redirect('admin/index.php');
$id=(int)($_GET['car_id']??0);$st=db()->prepare('SELECT * FROM cars WHERE id=? AND active=1');$st->execute([$id]);$car=$st->fetch();if(!$car) redirect('index.php');
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{verifyCsrf();$from=trim($_POST['from_city']??'');$to=trim($_POST['to_city']??'');$pickup=$_POST['pickup_date']??'';$return=$_POST['return_date']??'';$km=(float)($_POST['total_km']??0);$days=bookingDays($pickup,$return);
 if(!$from||!$to||!$pickup||!$return||$days<=0||$km<=0)throw new RuntimeException('Enter valid cities, dates and route KM.');
 $pdo=db();$pdo->beginTransaction();$lock=$pdo->prepare('SELECT * FROM cars WHERE id=? AND active=1 FOR UPDATE');$lock->execute([$id]);$c=$lock->fetch();$q=$pdo->prepare("SELECT id FROM bookings WHERE car_id=? AND status='confirmed' AND pickup_date < ? AND return_date > ? LIMIT 1");$q->execute([$id,$return,$pickup]);if($q->fetch()){ $pdo->rollBack();throw new RuntimeException('This vehicle is already booked for the selected dates.'); }
 $day=(float)$c['day_price']*$days;$kmc=(float)$c['km_price']*$km;$total=$day+$kmc;$code='JNR-'.date('Ymd').'-'.strtoupper(bin2hex(random_bytes(3)));
 $q=$pdo->prepare('INSERT INTO bookings(booking_code,car_id,customer_id,customer_name,customer_phone,customer_email,from_city,to_city,pickup_date,return_date,total_km,days,day_charge,km_charge,total_amount) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$u=user();$q->execute([$code,$id,$u['id'],$u['name'],$u['phone']??'',$u['email'],$from,$to,$pickup,$return,$km,$days,$day,$kmc,$total]);$bid=$pdo->lastInsertId();$pdo->commit();flash('success','Booking '.$code.' confirmed.');redirect('customer.php');
 }catch(Throwable $e){if(isset($pdo)&&$pdo instanceof PDO&&$pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}
}
pageTop('Book '.$car['name']);nav();?><main class="container narrow"><div class="booking-layout"><section class="panel"><p class="eyebrow">RESERVE VEHICLE</p><h1><?=e($car['name'])?></h1><p class="muted"><?=e($car['type'])?> · <?=e($car['seats'])?> seats</p><div class="booking-car"><img src="<?=e($car['image_url'])?>" onerror="this.src='https://placehold.co/900x550/1c1410/d4a373?text=<?=rawurlencode($car['name'])?>'" alt=""></div><div class="specs"><span><?=e($car['fuel'])?></span><span><?=e($car['transmission'])?></span><span><?=e($car['ac'])?></span></div></section><section class="panel"><h2>Booking details</h2><?php if($error): ?><div class="flash error"><?=e($error)?></div><?php endif; ?><form method="post" class="form-grid" id="bookForm"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>From city<input id="from_city" name="from_city" required placeholder="Anand"></label><label>To city<input id="to_city" name="to_city" required placeholder="Ahmedabad"></label><label>Pickup date<input id="pickup_date" type="date" name="pickup_date" required></label><label>Return date<input id="return_date" type="date" name="return_date" required></label><label>Live road distance (KM)<input id="total_km" name="total_km" type="number" step="0.1" min="1" required><small id="routeStatus" class="muted">Enter both cities to calculate road KM.</small></label><div id="map" class="map"></div><div class="summary"><div><span>Daily rate</span><b><?=money((float)$car['day_price'])?></b></div><div><span>KM rate</span><b><?=money((float)$car['km_price'])?></b></div><div><span>Estimated total</span><strong id="estimate">₹0.00</strong></div></div><button class="btn primary" type="submit">Confirm Booking</button></form></section></div></main><link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script>const dayRate=<?=json_encode((float)$car['day_price'])?>,kmRate=<?=json_encode((float)$car['km_price'])?>;let map,routeLayer,markers=[];function initMap(){map=L.map('map').setView([22.7,72.9],8);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap contributors'}).addTo(map)}async function geo(q){let r=await fetch('https://nominatim.openstreetmap.org/search?format=json&limit=1&q='+encodeURIComponent(q));let d=await r.json();return d[0]?{lat:+d[0].lat,lon:+d[0].lon,name:d[0].display_name}:null}async function route(){let a=document.getElementById('from_city').value.trim(),b=document.getElementById('to_city').value.trim();if(!a||!b)return;document.getElementById('routeStatus').textContent='Calculating live road distance…';try{let A=await geo(a),B=await geo(b);if(!A||!B)throw new Error('City not found');let r=await fetch(`https://router.project-osrm.org/route/v1/driving/${A.lon},${A.lat};${B.lon},${B.lat}?overview=full&geometries=geojson`);let j=await r.json();if(!j.routes?.[0])throw new Error('Route unavailable');let km=j.routes[0].distance/1000;document.getElementById('total_km').value=km.toFixed(1);document.getElementById('routeStatus').textContent='Live road distance: '+km.toFixed(1)+' km';if(routeLayer)map.removeLayer(routeLayer);markers.forEach(m=>map.removeLayer(m));markers=[L.marker([A.lat,A.lon]).addTo(map).bindPopup('From: '+A.name),L.marker([B.lat,B.lon]).addTo(map).bindPopup('To: '+B.name)];routeLayer=L.geoJSON(j.routes[0].geometry).addTo(map);map.fitBounds(routeLayer.getBounds(),{padding:[20,20]});calc()}catch(e){document.getElementById('routeStatus').textContent='Could not calculate automatically. You can enter KM manually.'}}function calc(){let p=document.getElementById('pickup_date').value,r=document.getElementById('return_date').value,km=+document.getElementById('total_km').value||0;if(p&&r){let days=(new Date(r)-new Date(p))/86400000;document.getElementById('estimate').textContent=new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR'}).format(Math.max(0,days)*dayRate+km*kmRate)}}['from_city','to_city'].forEach(id=>document.getElementById(id).addEventListener('change',route));['pickup_date','return_date','total_km'].forEach(id=>document.getElementById(id).addEventListener('input',calc));initMap();</script><?php pageBottom(); ?>